"""Synthetic ShopCo data, generated by Spark itself.

No public clickstream matches ShopCo's shape, so we make one (local/adr/0002).
The generator is deterministic for a given seed and produces the same quirks at
every scale: anonymous (NULL) users, one bot key with 3% of all traffic, power
users (quadratic skew), hot products (cubic skew), and a products table that is
small in rows but wide in bytes.
"""

from __future__ import annotations

import datetime as dt

from pyspark.sql import DataFrame, SparkSession, functions as F

from shopco import config as C
from shopco.config import Paths, Scale


def _event_type_expr(u) -> F.Column:
    expr = None
    for name, threshold in C.EVENT_TYPE_THRESHOLDS:
        expr = F.when(u < threshold, F.lit(name)) if expr is None else expr.when(u < threshold, F.lit(name))
    return expr.otherwise(F.lit("view"))


def _country_expr(u) -> F.Column:
    expr = None
    cumulative = 0.0
    for country, share, _region in C.COUNTRIES:
        cumulative += share
        expr = F.when(u < cumulative, F.lit(country)) if expr is None else expr.when(u < cumulative, F.lit(country))
    return expr.otherwise(F.lit(C.COUNTRIES[-1][0]))


def _region_expr(country_col) -> F.Column:
    expr = None
    for country, _share, region in C.COUNTRIES:
        cond = country_col == country
        expr = F.when(cond, F.lit(region)) if expr is None else expr.when(cond, F.lit(region))
    return expr.otherwise(F.lit("OTHER"))


def price_expr(product_id) -> F.Column:
    """Deterministic price per product, so events and the products table agree without a join."""
    return F.round(F.lit(5.0) + F.pmod(product_id * F.lit(7919), F.lit(495)) + F.lit(0.99), 2)


def events_for_day(spark: SparkSession, scale: Scale, day: dt.date, seed: int) -> DataFrame:
    day_epoch = int(dt.datetime(day.year, day.month, day.day, tzinfo=dt.timezone.utc).timestamp())
    s = seed + day.toordinal() * 13
    df = spark.range(0, scale.events_per_day, numPartitions=scale.gen_partitions)
    df = (
        df.withColumn("u_user", F.rand(s + 1))
        .withColumn("u_time", F.rand(s + 2))
        .withColumn("u_type", F.rand(s + 3))
        .withColumn("u_prod", F.rand(s + 4))
        .withColumn("u_junk", F.rand(s + 5))
    )
    user_id = (
        F.when(F.col("u_junk") < C.NULL_USER_FRACTION, F.lit(None).cast("long"))
        .when(F.col("u_junk") < C.NULL_USER_FRACTION + C.BOT_EVENT_FRACTION, F.lit(C.BOT_USER_ID).cast("long"))
        # u^2 pushes mass toward low ids: a minority of power users create most events
        .otherwise((F.pow(F.col("u_user"), 2.0) * F.lit(scale.customers)).cast("long") + F.lit(1))
    )
    # u^3: a few hot products take most of the clicks
    product_id = (F.pow(F.col("u_prod"), 3.0) * F.lit(scale.products)).cast("long")
    return (
        df.withColumn("user_id", user_id)
        .withColumn("ts", F.timestamp_seconds(F.lit(day_epoch) + (F.col("u_time") * 86400).cast("long")))
        .withColumn("event_type", _event_type_expr(F.col("u_type")))
        .withColumn("product_id", product_id)
        .withColumn("price", price_expr(product_id))
        .select("user_id", "ts", "event_type", "product_id", "price")
    )


def customers_df(spark: SparkSession, scale: Scale, seed: int) -> DataFrame:
    parts = max(2, scale.customers // 500_000)
    df = spark.range(1, scale.customers + 1, numPartitions=parts).withColumnRenamed("id", "user_id")
    df = df.withColumn("u_country", F.rand(seed + 101)).withColumn("u_signup", F.rand(seed + 102))
    country = _country_expr(F.col("u_country"))
    return (
        df.withColumn("country", country)
        .withColumn("region", _region_expr(F.col("country")))
        .withColumn("signup_date", F.date_sub(F.lit(C.START_DATE), (F.col("u_signup") * 1095).cast("int")))
        .select("user_id", "country", "region", "signup_date")
    )


def products_df(spark: SparkSession, scale: Scale) -> DataFrame:
    df = spark.range(0, scale.products, numPartitions=1).withColumnRenamed("id", "product_id")
    return (
        df.withColumn("category", F.concat(F.lit("cat_"), F.pmod(F.col("product_id"), F.lit(C.N_CATEGORIES))))
        .withColumn("title", F.concat(F.lit("Product "), F.col("product_id")))
        # ~330 bytes/row makes 50K rows > 10 MB: too big for Spark's auto-broadcast (course M3)
        .withColumn("description", F.repeat(F.lit("lorem ipsum dolor sit amet consectetur "), 9))
        .withColumn("price", price_expr(F.col("product_id")))
        .select("product_id", "category", "title", "description", "price")
    )


def generate_all(spark: SparkSession, scale: Scale, paths: Paths, monitor, seed: int = 42) -> None:
    """Write events (one directory per day), customers and products as Parquet."""
    with monitor.step("gen_customers") as h:
        customers_df(spark, scale, seed).write.mode("overwrite").parquet(paths.customers)
        h.note(rows=scale.customers)

    with monitor.step("gen_products") as h:
        products_df(spark, scale).write.mode("overwrite").parquet(paths.products)
        h.note(rows=scale.products)

    for i in range(scale.days):
        day = C.START_DATE + dt.timedelta(days=i)
        with monitor.step(f"gen_events_{day.isoformat()}") as h:
            # Writing straight into dt=<day>/ gives Hive-style partitioning on read,
            # with exactly gen_partitions files per day (no small-files problem).
            events_for_day(spark, scale, day, seed).write.mode("overwrite").parquet(f"{paths.events}/dt={day.isoformat()}")
            h.note(rows=scale.events_per_day, day=day.isoformat())
